<script lang="ts">
	import { getContext, type Snippet } from "svelte";

    /**
     * @description
     * A single tab panel within a TabbedContent. Registers itself with the parent TabbedContent via context.
     * @example
     * <TabbedContent>
     *     <TabbedContentItem label="First">
     *         <p>First tab content</p>
     *     </TabbedContentItem>
     * </TabbedContent>
     */
    let {
        id,
        label,
        href,
        children,
    }: {
        /** Unique identifier for this tab. Defaults to a slug of `label`. */
        id?: string;
        /** The label displayed in the tab bar. */
        label: string;
        /** Optional URL hash for this tab. */
        href?: string;
        /** The content of this tab panel. */
        children: Snippet;
    } = $props();

    if(!id) {
        id = label.toLowerCase().replace(/ /g, '-');
    }

    if(href && !href.startsWith('#')) {
        href = `#${encodeURIComponent(href)}`;
    }

    const setTabItem = getContext<((id: string, label: string, href?: string) => void)>('TabbedContent.setTabItem');
    setTabItem(id, label, href);
</script>

<div class="TabbedContentItem">
    {@render children()}
</div>

